using System.ComponentModel.DataAnnotations;

namespace RecipeSharing.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    [Required]
    public string Ingredients { get; set; } = string.Empty;

    [Required]
    public string Steps { get; set; } = string.Empty;

    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public static class RecipeStore
{
    private static readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread crushed tomatoes\n4. Add torn mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil and olive oil",
            Ratings = new List<int> { 5, 4, 5 }
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook pasta al dente\n2. Crisp guanciale in pan\n3. Whisk eggs with cheese and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture\n6. Serve immediately",
            Ratings = new List<int> { 5, 5, 4, 5 }
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nTomato sauce\nCream\nOnion\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or broil chicken\n3. Sauté onion, garlic, ginger\n4. Add tomato sauce and spices\n5. Simmer, add cream\n6. Add chicken pieces\n7. Serve with rice or naan",
            Ratings = new List<int> { 4, 5, 4 }
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs\nGreen onions",
            Steps = "1. Soak rice noodles\n2. Make sauce with tamarind, fish sauce, sugar\n3. Fry tofu until golden\n4. Scramble eggs in pan\n5. Add noodles and sauce\n6. Toss with bean sprouts\n7. Garnish with peanuts, lime, green onions",
            Ratings = new List<int> { 4, 4, 5 }
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm tortillas\n5. Fill with beef and toppings\n6. Serve with salsa and sour cream",
            Ratings = new List<int> { 4, 3, 5, 4 }
        },
        new Recipe
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until thick\n3. Fold in chocolate mixture\n4. Add flour and vanilla\n5. Pour into greased ramekins\n6. Bake at 425°F for 12 minutes\n7. Invert onto plates and serve immediately",
            Ratings = new List<int> { 5, 5, 5 }
        }
    };

    public static IReadOnlyList<Recipe> All => _recipes;

    public static IEnumerable<string> Categories =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c);

    public static IEnumerable<Recipe> ByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public static void Add(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public static void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe != null && stars >= 1 && stars <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _displayRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0">
            &#9733;
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>
<div class="average-rating">
    Average: @AverageRating.ToString("0.0") / 5 (@RatingCount ratings)
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _hoverRating;
    private int _selectedRating;
    private bool _submitted;

    private int _displayRating => _hoverRating > 0 ? _hoverRating : _selectedRating;

    private void Rate(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        RecipeStore.AddRating(RecipeId, stars);
        AverageRating = RecipeStore.GetById(RecipeId)?.AverageRating ?? AverageRating;
        RatingCount++;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    margin: 1rem 0 0.5rem;
}

.rating-label {
    margin-right: 0.5rem;
    font-weight: 500;
}

.star {
    font-size: 1.75rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star.filled {
    color: #f5a623;
}

.star:hover {
    color: #f5a623;
}

.rating-thanks {
    margin-left: 0.75rem;
    color: #28a745;
    font-weight: 500;
}

.average-rating {
    color: #666;
    font-size: 0.9rem;
}

